 "content": "def transform(grid):
    # Recolor isolated interior gaps of each vertical stroke; pattern is the
    # cells that are adjacent vertically to an existing mark at either end?
    # In demonstrations the marked positions are replaced by color 2 on a
    # regular alternating sequence where one of two parallel strokes marks it.
    # Infer parity from row, based on the first sparse stroke.
    out = [row[:] for row in grid]
    colors = {v for row in grid for v in row}
    bg = max(colors, key=lambda c: sum(row.count(c) for row in grid))
    ink = next(c for c in colors if c != bg)
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v == ink and 0 < r < len(grid)-1 and grid[r-1][c] == bg and grid[r+1][c] == bg:
                out[r][c] = 2
    return out
